builder.Services.AddAuthorizationBuilder()
    .AddPolicy("CanManageOrders", p => p
        .RequireAuthenticatedUser()
        .RequireClaim("scope", "orders.write"))
    .AddPolicy("Adult", p => p.AddRequirements(new MinimumAgeRequirement(18)));

builder.Services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>();

app.MapDelete("/api/orders/{id}", DeleteOrder).RequireAuthorization("CanManageOrders");

app.MapGet("/api/orders/{id:int}", async Task<Results<Ok<OrderDto>, NotFound>> (
    int id, ClaimsPrincipal user, AppDbContext db, CancellationToken ct) =>
{
    var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
    var order = await db.Orders
        .Where(o => o.Id == id && o.UserId == userId)   // kontrola własności
        .Select(o => new OrderDto(o.Id, o.Total))
        .FirstOrDefaultAsync(ct);
    return order is null ? TypedResults.NotFound() : TypedResults.Ok(order);
}).RequireAuthorization();

